// Datenpunkte
createState('Wolken-PV_Halle.Wolkenzaehler_PVHalle_Aktiv', false, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{ "role" : "switch" , "type" : "boolean" , "name" : "WolkenzaehlerPVCaddyAktiv" , "smartName" : { "de" : "Verzögerung WP" , "smartType" : "SWITCH" }}'), async () => {
});
createState('Wolken-PV_Halle.Wolkenzaehler_PVHalle', 10, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "Wolkenzaehler PV Halle","role": "","type": "number","desc": "Blockly erzeugt","unit": "","min": 0,"max": 10,"def": 0,"read": true,"write": true}'), async () => {
});
setState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle' /* Wolkenzaehler PV Halle */, 10);
createState('Wolken-PV_Halle.Wolkenzaehler_PVHalle_Merker', 0, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "Wolkenzaehler PV Halle Merker","role": "","type": "number","desc": "Blockly erzeugt","unit": "","min": 0,"max": 100000,"def": 0,"read": true,"write": true}'), async () => {
});
// Neustart
schedule({ astro: 'night', shift: 0 }, async () => {
  setState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle_Aktiv' /* WolkenzaehlerPVCaddyAktiv */, false);
  setState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle' /* Wolkenzaehler PV Halle */, 10);
});
// Wolkenzähler
schedule('{"time":{"start":"sunrise","end":"sunset","mode":"minutes","interval":10},"period":{"days":1}}', async () => {
  if (getState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle_Aktiv').val) {
    if (getState('alias.0.Fronius.AC-Power').val >= 5000) {
      setState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle' /* Wolkenzaehler PV Halle */, (Math.min(Math.max(getState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle').val - 1, 0), 10)));
    }
    if (getState('alias.0.Fronius.AC-Power').val < 3000) {
      setState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle' /* Wolkenzaehler PV Halle */, (Math.min(Math.max(getState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle').val + 1, 0), 10)));
    }
  } else {
    setState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle' /* Wolkenzaehler PV Halle */, 10);
  }
});
// bei Sonneneinbruch, den Zähler resetten
schedule("*/5 * * * * *", async () => {
  if (getState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle_Aktiv').val) {
    if (getState('alias.0.Fronius.AC-Power').val < getState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle_Merker').val - 500) {
      setState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle' /* Wolkenzaehler PV Halle */, 10);
    }
    setState('javascript.0.Wolken-PV_Halle.Wolkenzaehler_PVHalle_Merker' /* Wolkenzaehler PV Halle Merker */, getState('alias.0.Fronius.AC-Power').val);
  }
});


